function encyclopediaRecentKey(app) {
  try {
    const vault = app && app.vault;
    const adapter = vault && vault.adapter;
    const identity = adapter && adapter.getBasePath ? adapter.getBasePath() : vault && vault.getName ? vault.getName() : "vault";
    return `nd-ency-recent-defs-${hashIdentity(String(identity || "vault"))}`;
  } catch (error) {
    return "nd-ency-recent-defs";
  }
}

